 40	/// Cleaned evidence whose identity and role references have been checked together.
 41	pub struct ResolutionInput {
 42	    pub(crate) observations: BTreeMap<FunderObservationId, Observation>,
 43	    pub(crate) payments: BTreeMap<FundingEntryId, Payment>,
 44	    pub(crate) digests: BTreeMap<String, String>,
