 47	impl ResolutionInput {
 48	    pub(crate) fn new(
 49	        observations: Vec<Observation>,
 50	        payments: Vec<Payment>,
 51	        digests: BTreeMap<String, String>,
 52	    ) -> Result<Self, EntityIngestionError> {
 53	        let mut input = Self {
 54	            observations: BTreeMap::new(),
 55	            payments: BTreeMap::new(),
 56	            digests,
 57	        };
 58	        let mut members = BTreeMap::new();
 59	        let mut declarations = BTreeMap::new();
 60	        for payment in payments {
 61	            check_payment(&payment, &mut members, &mut declarations)?;
 62	            if input
 63	                .payments
 64	                .insert(payment.funding_entry_id.clone(), payment)
 65	                .is_some()
 66	            {
 67	                return Err(invalid("duplicate funding occurrence ID"));
 68	            }
 69	        }
 70	        for observation in observations {
 71	            check_observation(&observation, &input, &mut declarations)?;
 72	            if input
 73	                .observations
 74	                .insert(observation.funder_id.clone(), observation)
 75	                .is_some()
 76	            {
 77	                return Err(invalid("duplicate funder observation ID"));
 78	            }
 79	        }
 80	        for payment in input.payments.values() {
 81	            for (id, role) in [
 82	                (&payment.donor_funder_id, FunderRole::Donor),
 83	                (&payment.payer_funder_id, FunderRole::Payer),
 84	                (&payment.ultimate_payer_funder_id, FunderRole::UltimatePayer),
 85	            ] {
 86	                if let Some(id) = id {
 87	                    let observation = input
 88	                        .observations
 89	                        .get(id)
 90	                        .ok_or_else(|| invalid("dangling payment role reference"))?;
 91	                    if observation.role != role
 92	                        || observation.funding_entry_id.as_ref() != Some(&payment.funding_entry_id)
 93	                    {
 94	                        return Err(invalid("payment role points to unrelated observation"));
 95	                    }
 96	                }
 97	            }
 98	        }
 99	        for observation in input.observations.values() {
100	            if let Some(id) = &observation.funding_entry_id {
101	                let payment = &input.payments[id];
102	                let role_id = match observation.role {
103	                    FunderRole::Donor => &payment.donor_funder_id,
104	                    FunderRole::Payer => &payment.payer_funder_id,
105	                    FunderRole::UltimatePayer => &payment.ultimate_payer_funder_id,
106	                };
107	                if role_id.as_ref() != Some(&observation.funder_id) {
108	                    return Err(invalid("unreferenced funding role observation"));
109	                }
110	            }
111	        }
112	        Ok(input)
113	    }
