115	    /// Groups repeated feature profiles without asserting that they identify the same funder.
116	    #[must_use]
117	    pub fn scoring_input(&self, candidate_budget: usize) -> ScoringInput {
118	        let mut groups = BTreeMap::<(String, Option<String>), Vec<FunderObservationId>>::new();
119	        for observation in self.observations.values() {
120	            if let Some(name) = &observation.name_normalized {
121	                groups
122	                    .entry((name.clone(), observation.address_normalized.clone()))
123	                    .or_default()
124	                    .push(observation.funder_id.clone());
125	            }
126	        }
127	        let mut rows = Vec::new();
128	        let mut members = BTreeMap::new();
129	        for (index, ((name, address), ids)) in groups.into_iter().enumerate() {
130	            let key = format!("profile-{index:08}");
131	            rows.push(ComparisonRow {
132	                key: key.clone(),
133	                name: name.clone(),
134	                address: address.clone(),
135	                needs_resolution: ids
136	                    .iter()
137	                    .any(|id| company(&self.observations[id]).is_none()),
138	            });
139	            members.insert(key.clone(), ids.clone());
140	            if ids.len() > 1
141	                && ids
142	                    .iter()
143	                    .any(|id| company(&self.observations[id]).is_none())
144	            {
145	                let copy = format!("{key}-repeat");
146	                rows.push(ComparisonRow {
147	                    key: copy.clone(),
148	                    name,
149	                    address,
150	                    needs_resolution: true,
151	                });
152	                members.insert(copy, ids);
153	            }
154	        }
155	        ScoringInput {
156	            version: 1,
157	            candidate_budget,
158	            rows,
159	            members,
160	        }
161	    }
162	}
