164	fn root_scope(pointer: &str) -> bool {
165	    let parts = pointer.split('/').collect::<Vec<_>>();
166	    parts.len() >= 4
167	        && parts[0].is_empty()
168	        && parts[1] == "versions"
169	        && parts[2].parse::<u32>().is_ok()
170	        && parts[3] == "fields"
171	        && (parts.len() - 4).is_multiple_of(3)
172	        && parts[4..].chunks(3).all(|chunk| {
173	            chunk[0].parse::<u32>().is_ok()
174	                && chunk[1] == "values"
175	                && chunk[2].parse::<u32>().is_ok()
176	        })
177	}
178	pub(super) fn is_root(pointer: &str) -> bool {
179	    pointer.split('/').count() == 4
180	}
