    57	fn strong(input: &ResolutionInput, edge: &PairDecision) -> bool {
    58	    let a = &input.observations[&edge.left_funder_id];
    59	    let b = &input.observations[&edge.right_funder_id];
    60	    edge.probability >= AUTOMATIC_THRESHOLD
    61	        && a.name_normalized.is_some()
    62	        && a.name_normalized == b.name_normalized
    63	        && a.address_match_quality == AddressMatchQuality::NumberedStreet
    64	        && b.address_match_quality == AddressMatchQuality::NumberedStreet
    65	        && a.address_normalized.is_some()
    66	        && a.address_normalized == b.address_normalized
    67	}
