    69	type CandidateEdges = BTreeMap<(FunderObservationId, FunderObservationId), PairDecision>;
    70	fn expanded_edges(
    71	    input: &ResolutionInput,
    72	    scoring: &ScoringInput,
    73	    pairs: Vec<ScoredPair>,
    74	) -> Result<CandidateEdges, EntityIngestionError> {
    75	    let mut edges = BTreeMap::new();
    76	    for pair in pairs {
    77	        for left in &scoring.members[&pair.left] {
    78	            for right in &scoring.members[&pair.right] {
    79	                if left == right {
    80	                    continue;
    81	                }
    82	                let (left, right) = if left < right {
    83	                    (left, right)
    84	                } else {
    85	                    (right, left)
    86	                };
    87	                let a = &input.observations[left];
    88	                let b = &input.observations[right];
    89	                if company(a).is_some() && company(b).is_some() {
    90	                    continue;
    91	                }
    92	                edges
    93	                    .entry((left.clone(), right.clone()))
    94	                    .or_insert_with(|| PairDecision {
    95	                        left_funder_id: left.clone(),
    96	                        right_funder_id: right.clone(),
    97	                        probability: pair.probability,
    98	                        name_level: pair.name_level,
    99	                        address_level: pair.address_level,
   100	                        disposition: PairDisposition::Review,
   101	                        reason: PairReason::InsufficientExactEvidence,
   102	                    });
   103	                if edges.len() > scoring.candidate_budget {
   104	                    return Err(invalid(
   105	                        "expanded observation pairs exceed candidate budget; raise candidate_budget explicitly",
   106	                    ));
   107	                }
   108	            }
   109	        }
   110	    }
   111	    Ok(edges)
   112	}
